{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "실행 계획에서 찾은 병목을 바탕으로 캐시보다 쿼리 자체의 개선을 선택한 판단을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 인턴 때 운영 화면의 신고 목록 조회에 3.2초가 걸렸다.",
          "task": "조회 지연의 원인에 맞는 개선 방법을 선택해야 했다.",
          "action": "실행 계획을 근거로 인덱스를 추가하고 조인 순서를 정리했다.",
          "result": "조회 시간이 0.4초로 줄어든 결과로 선택의 효과를 설명한다."
        },
        "expectedEvidence": [
          "캐시 대신 쿼리를 개선한 이유를 병목의 특성과 연결한다.",
          "실행 계획에서 확인한 문제와 인덱스 및 조인 개선을 연결한다.",
          "3.2초에서 0.4초로 줄어든 측정 결과로 선택을 뒷받침한다."
        ]
      },
      "question": "포켓마켓 인턴 때 인덱스 추가와 조인 정리로 신고 목록 조회를 3.2초에서 0.4초로 줄이셨던데요. 캐시 대신 쿼리를 고친 이유는 무엇이었나요?",
      "answerTip": "당시 실제로 한 판단을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "캐시 대신 쿼리를 개선한 이유를 실행 계획에서 확인한 병목과 구체적으로 연결한다.",
            "인덱스와 조인 개선의 작용을 설명하고 전후 응답 시간으로 선택을 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "쿼리를 개선한 이유는 설명하지만 실행 계획이나 개선 결과와의 연결은 일반적이다."
          ]
        },
        "poor": {
          "criteria": [
            "쿼리를 개선한 이유를 설명하지 못하고 작업 내용이나 결과 수치만 반복한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "로그로 찾은 중복 실행 원인에 맞춰 복구와 재발 방지를 위한 잠금 방식을 선택한 판단을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 인턴 때 배포 후 두 서버의 스케줄러가 동시에 실행돼 알림이 중복 발송됐다.",
          "task": "중복 발송을 멈추고 같은 실행 충돌이 반복되지 않게 해야 했다.",
          "action": "시간순 로그로 원인을 좁히고 잠금 키를 두는 방식으로 수정했다.",
          "result": "중복 실행 차단이 당장의 복구와 이후 재발 방지에 갖는 의미를 설명한다."
        },
        "expectedEvidence": [
          "한 서버에서만 실행하는 방법 대신 잠금을 선택한 이유를 설명한다.",
          "로그에서 찾은 두 서버의 동시 실행과 잠금의 차단 범위를 연결한다.",
          "당장의 중복 발송 중단과 이후 재발 방지에서 잠금의 역할을 구분한다."
        ]
      },
      "question": "포켓마켓 인턴 때 두 서버의 스케줄러 중복 실행을 잠금으로 고치셨던데요. 한 서버에서만 실행하는 방법 대신 왜 잠금을 선택하셨나요?",
      "answerTip": "선택의 이유가 드러나도록 구체적으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "잠금을 선택한 이유를 로그에서 확인한 동시 실행 원인과 연결해 설명한다.",
            "한 서버에서만 실행하는 방법과 비교해 잠금의 복구 및 재발 방지 역할을 구체화한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "잠금을 선택한 이유는 답하지만 동시 실행 원인이나 재발 방지와의 연결이 일반적이다."
          ]
        },
        "poor": {
          "criteria": [
            "잠금을 선택한 이유를 설명하지 못하거나 로그 추적 내용만 반복한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "세탁소 인터뷰에서 나온 요구를 서비스 목적과 구현 제약에 비추어 개발 범위로 구체화한 판단을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "세탁소 다섯 곳의 인터뷰를 바탕으로 예약 서비스 요구사항을 정의한 과제였다.",
          "task": "인터뷰에서 나온 요구 중 개발 범위에 포함할 대상을 정해야 했다.",
          "action": "서비스 목적과 구현 제약을 근거로 요구사항의 포함 여부와 우선순위를 정했다.",
          "result": "개발 담당 팀원과 합의한 구현 범위가 요구사항 정의서에 구체적으로 드러났다."
        },
        "expectedEvidence": [
          "개발 범위에 포함할 요구를 고른 근거를 설명한다.",
          "실제 요구의 포함 여부를 서비스 목적이나 구현 제약과 연결한다.",
          "선택한 범위가 요구사항 정의서에 구체화된 사례를 제시한다."
        ]
      },
      "question": "세탁소 예약 서비스 과제에서 다섯 곳의 인터뷰를 바탕으로 개발 담당 팀원과 범위를 조정하셨던데요. 개발 범위에 포함할 요구는 무엇을 근거로 고르셨나요?",
      "answerTip": "당시 실제로 내린 판단을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제 요구를 예로 들어 포함 여부를 결정한 근거를 서비스 목적이나 구현 제약과 연결한다.",
            "그 판단이 요구사항 정의서의 구체적인 구현 범위로 이어진 사례를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "개발 범위에 포함할 요구를 고른 근거는 설명하지만 실제 요구와의 연결이 일반적이다."
          ]
        },
        "poor": {
          "criteria": [
            "인터뷰나 문서 작성 사실만 반복하고 개발 범위를 선택한 근거를 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황에서 사용자가 보게 될 화면 상태를 기능 흐름에 맞게 구체화한 판단을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "세탁소 예약 서비스 과제에서 예외 상황을 포함한 화면설계서 28장을 작성했다.",
          "task": "예외 상황에서 표시할 화면 상태를 구현 가능한 수준으로 정해야 했다.",
          "action": "예외 발생 시점의 처리 상태와 사용자의 다음 행동을 근거로 화면을 설계했다.",
          "result": "예외 발생 후 표시할 상태와 안내가 화면설계서에서 명확하게 연결되었다."
        },
        "expectedEvidence": [
          "예외 상황에서 보여 줄 화면 상태를 정한 근거를 설명한다.",
          "구체적인 예외 사례에서 정상 흐름과 달라지는 화면 상태를 짚는다.",
          "해당 화면의 안내를 사용자가 이어갈 행동과 연결한다."
        ]
      },
      "question": "세탁소 예약 서비스 과제에서 예외 상황을 담은 화면설계서 28장을 작성하셨던데요. 예외 상황에서 보여 줄 화면 상태를 정한 근거는 무엇이었나요?",
      "answerTip": "직접 작성했던 화면을 떠올리며 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "구체적인 예외 사례를 들어 정상 흐름과 달라지는 화면 상태를 정한 근거를 설명한다.",
            "그 화면의 안내가 사용자의 다음 행동과 연결되는 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "화면 상태를 정한 근거는 답하지만 구체적인 예외 사례나 다음 행동과의 연결이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "예외 화면을 작성했다는 사실만 말하거나 화면 상태를 정한 근거를 설명하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "평소와 다른 용량이 의도적인 증량일 가능성에도 투약을 보류한 판단 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원에서 수술 후 환자의 진통제 용량이 평소의 두 배로 처방되었다.",
          "task": "처방 용량의 적절성이 확인되지 않은 상태에서 투약 여부를 판단해야 했다.",
          "action": "용량 변경의 근거가 확인되지 않아 투약을 멈추고 담당의에게 확인했다.",
          "result": "담당의 확인으로 입력 오류를 발견해 잘못된 용량의 투약을 막았다."
        },
        "expectedEvidence": [
          "의도적인 증량으로 단정하지 않고 투약을 보류한 근거를 설명한다.",
          "용량 변경의 불확실성을 담당의에게 확인해 해소한 내용을 제시한다."
        ]
      },
      "question": "푸른결종합병원에서 평소 두 배인 진통제 처방의 투약을 멈추셨던데요. 의도적인 증량일 수도 있는 처방을 바로 투약하지 않은 판단 근거는 무엇이었나요?",
      "answerTip": "당시 실제로 판단한 내용을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "단순히 평소와 다르다는 설명을 넘어, 용량 변경의 근거가 불확실했던 지점을 구체적으로 설명한다.",
            "담당의에게 확인한 내용으로 투약을 보류한 판단의 근거를 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "용량이 의심스러워 투약을 보류했다고 답하지만, 확인이 필요했던 이유는 일반적인 안전 원칙에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 보류한 판단 근거를 설명하지 못하거나, 오류였다는 사후 결과만 반복한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "진통제 투여 시각을 인수인계에 포함한 선택을 다음 근무자의 상태 변화 관찰과 연결하는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 수술 후 첫 보행 환자의 낙상이 근무 교대 시간대에 몰렸다.",
          "task": "교대 후에도 환자 상태를 놓치지 않도록 인수인계에 필요한 정보를 골라야 했다.",
          "action": "진통제 투여 시각이 상태 변화 해석에 필요한 이유를 바탕으로 인수인계 항목에 추가했다.",
          "result": "다음 근무자가 투약 이후의 상태 변화를 이어서 관찰할 수 있는 정보가 전달된다."
        },
        "expectedEvidence": [
          "투여 시각 누락으로 다음 근무자가 놓칠 수 있는 상태 변화를 설명한다.",
          "투여 시각과 환자 상태를 연결해 인수인계에 포함할 필요성을 뒷받침한다."
        ]
      },
      "question": "푸른결종합병원에서 낙상 예방 인수인계표에 진통제 투여 시각을 넣으셨던데요. 그 시각이 빠지면 다음 근무자의 환자 상태 관찰에 어떤 공백이 생길 수 있었나요?",
      "answerTip": "그때의 상황을 떠올려 구체적으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "투여 시각이 없으면 놓치거나 잘못 해석할 수 있는 환자 상태 변화를 구체적으로 설명한다.",
            "투약 이후 상태 관찰을 이어가는 데 해당 정보가 필요한 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "다음 근무자의 상태 관찰에 공백이 생긴다고 답하지만, 투여 시각과의 연결은 막연하다."
          ]
        },
        "poor": {
          "criteria": [
            "상태 관찰의 공백을 설명하지 못하고, 추가한 항목이나 낙상 감소 수치만 반복한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P04",
  "interviews": [
    {
      "categoryId": "P04-C1",
      "itemId": "P04-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "축 지름의 선정 근거를 하중이 전달되는 경로와 지지 조건에 연결해 설명할 수 있는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "기계요소설계 개인 과제에서 주어진 하중으로 축 지름과 베어링을 선정했다.",
          "task": "주어진 하중을 견디는 축 지름을 계산하고 선정 근거를 설명해야 했다.",
          "action": "축에 전달되는 하중과 베어링의 지지 조건을 바탕으로 필요한 축 지름을 판단했다.",
          "result": "선정한 축 지름이 하중을 견딜 수 있다는 근거를 계산서와 연결해 설명한다."
        },
        "expectedEvidence": [
          "선정한 축 지름이 주어진 하중을 견딘다고 본 근거를 설명한다.",
          "베어링의 지지 조건이 축에 걸리는 하중에 미친 영향을 짚는다."
        ]
      },
      "question": "기계요소설계 과제에서 축 지름과 베어링을 선정하셨던데요. 선정한 축 지름이 주어진 하중을 견딘다고 판단한 근거는 무엇이었나요?",
      "answerTip": "당시 실제로 판단했던 내용을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
